import { useCallback, useEffect, useMemo, useState } from 'react';
import { AlertTriangle, Box, Check, Clock3, Loader2, MapPin, PackageCheck, Phone, Truck } from 'lucide-react';
import { apiRequest } from '@/lib/api';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';

type Delivery = { id: string; trackingCode: string; status: string; recipientName: string; recipientPhone: string; county: string; addressLine: string; landmark?: string; instructions?: string; courierName?: string; courierPhone?: string; estimatedStart?: string; order: { orderNumber: string; customer: { firstName: string; lastName: string } }; items: { id: string; name: string; quantity: number }[]; };
const nextAction: Record<string, { status: string; label: string }> = { PENDING: { status: 'PREPARING', label: 'Start preparing' }, PREPARING: { status: 'READY_FOR_PICKUP', label: 'Mark ready' }, READY_FOR_PICKUP: { status: 'PICKED_UP', label: 'Confirm pickup' }, COURIER_ASSIGNED: { status: 'PICKED_UP', label: 'Confirm pickup' }, PICKED_UP: { status: 'IN_TRANSIT', label: 'Start delivery' }, IN_TRANSIT: { status: 'ARRIVING', label: 'Mark arriving' }, ARRIVING: { status: 'DELIVERED', label: 'Confirm handoff' } };
const groups = ['ACTION', 'ACTIVE', 'DONE'] as const;

export function VendorDeliveries() {
  const [deliveries, setDeliveries] = useState<Delivery[]>([]);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState('');
  const [error, setError] = useState('');
  const [pin, setPin] = useState<Record<string, string>>({});
  const [courier, setCourier] = useState<Record<string, { courierName: string; courierPhone: string }>>({});
  const load = useCallback(() => apiRequest<Delivery[]>('/orders/vendor/fulfillments').then(setDeliveries).catch((cause) => setError(cause instanceof Error ? cause.message : 'Unable to load deliveries.')).finally(() => setLoading(false)), []);
  useEffect(() => { void load(); }, [load]);
  const counts = useMemo(() => ({ action: deliveries.filter((item) => item.status === 'PENDING' || item.status === 'DELIVERY_FAILED').length, active: deliveries.filter((item) => !['PENDING','DELIVERED','RETURNED','CANCELLED','DELIVERY_FAILED'].includes(item.status)).length, done: deliveries.filter((item) => item.status === 'DELIVERED').length }), [deliveries]);
  const update = async (delivery: Delivery, status: string) => { setBusy(delivery.id); setError(''); try { const detail = status === 'DELIVERED' ? 'Recipient handoff confirmed with delivery PIN.' : undefined; await apiRequest(`/orders/vendor/fulfillments/${delivery.id}/status`, { method: 'PATCH', body: JSON.stringify({ status, deliveryPin: pin[delivery.id], detail, ...courier[delivery.id] }) }); await load(); } catch (cause) { setError(cause instanceof Error ? cause.message : 'Unable to update delivery.'); } finally { setBusy(''); } };
  const bucket = (delivery: Delivery) => delivery.status === 'DELIVERED' || delivery.status === 'RETURNED' || delivery.status === 'CANCELLED' ? 'DONE' : delivery.status === 'PENDING' || delivery.status === 'DELIVERY_FAILED' ? 'ACTION' : 'ACTIVE';
  if (loading) return <div className="min-h-[420px] flex items-center justify-center"><Loader2 className="h-7 w-7 text-primary animate-spin"/></div>;
  return <div className="max-w-7xl mx-auto space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-300">
    <div className="flex flex-col md:flex-row md:items-end justify-between gap-4"><div><p className="text-xs font-bold text-primary uppercase tracking-widest">Fulfilment control</p><h1 className="text-3xl font-extrabold mt-2">Delivery desk</h1><p className="text-sm text-gray-500 mt-1">Prepare orders, coordinate pickup and verify every handoff.</p></div><div className="flex gap-2">{[[counts.action,'Needs action'],[counts.active,'Active'],[counts.done,'Delivered']].map(([value,label])=><div key={String(label)} className="bg-white border rounded-xl px-4 py-2"><span className="font-extrabold">{value}</span><span className="text-xs text-gray-500 ml-2">{label}</span></div>)}</div></div>
    {error && <div className="rounded-2xl bg-red-50 text-red-700 p-4 text-sm flex items-center gap-2"><AlertTriangle className="h-4 w-4"/>{error}</div>}
    <div className="grid xl:grid-cols-3 gap-5">{groups.map((group) => <section key={group} className="space-y-3"><div className="flex items-center justify-between px-1"><h2 className="text-xs font-extrabold uppercase tracking-[0.14em] text-gray-500">{group === 'ACTION' ? 'Needs action' : group === 'ACTIVE' ? 'In progress' : 'Completed'}</h2><span className="text-xs bg-gray-200 rounded-full px-2 py-0.5">{deliveries.filter((item) => bucket(item) === group).length}</span></div>{deliveries.filter((item) => bucket(item) === group).map((delivery) => {
      const action = nextAction[delivery.status];
      return <article key={delivery.id} className="bg-white border border-gray-200 rounded-2xl p-5 shadow-sm"><div className="flex items-start justify-between gap-3"><div className="w-10 h-10 rounded-xl bg-primary/10 text-primary flex items-center justify-center"><Box className="h-5 w-5"/></div><span className={`text-[10px] font-bold px-2 py-1 rounded-full ${delivery.status === 'DELIVERY_FAILED' ? 'bg-red-100 text-red-700' : delivery.status === 'DELIVERED' ? 'bg-green-100 text-green-700' : 'bg-blue-100 text-blue-700'}`}>{delivery.status.replaceAll('_',' ')}</span></div><p className="text-xs text-gray-400 font-mono mt-4">{delivery.trackingCode}</p><h3 className="font-extrabold mt-1">Order {delivery.order.orderNumber}</h3><div className="mt-4 space-y-2 text-sm"><div className="flex gap-2"><PackageCheck className="h-4 w-4 text-gray-400 mt-0.5"/><span>{delivery.items.map((item) => `${item.quantity}× ${item.name}`).join(', ')}</span></div><div className="flex gap-2"><MapPin className="h-4 w-4 text-gray-400 mt-0.5"/><span>{delivery.addressLine}, {delivery.county}{delivery.landmark ? ` · ${delivery.landmark}` : ''}</span></div><a href={`tel:${delivery.recipientPhone}`} className="flex gap-2 text-primary font-semibold"><Phone className="h-4 w-4 mt-0.5"/>{delivery.recipientName} · {delivery.recipientPhone}</a>{delivery.estimatedStart && <div className="flex gap-2 text-gray-500"><Clock3 className="h-4 w-4 mt-0.5"/>Due {new Date(delivery.estimatedStart).toLocaleDateString('en-KE', { day: 'numeric', month: 'short' })}</div>}</div>
        {delivery.status === 'READY_FOR_PICKUP' && <div className="grid grid-cols-2 gap-2 mt-4"><Input placeholder="Courier name" value={courier[delivery.id]?.courierName ?? ''} onChange={(event) => setCourier({ ...courier, [delivery.id]: { courierName: event.target.value, courierPhone: courier[delivery.id]?.courierPhone ?? '' } })}/><Input placeholder="Courier phone" value={courier[delivery.id]?.courierPhone ?? ''} onChange={(event) => setCourier({ ...courier, [delivery.id]: { courierPhone: event.target.value, courierName: courier[delivery.id]?.courierName ?? '' } })}/></div>}
        {delivery.status === 'ARRIVING' && <div className="mt-4"><label className="text-xs font-bold text-gray-500">Recipient delivery PIN</label><Input inputMode="numeric" maxLength={4} placeholder="4-digit PIN" value={pin[delivery.id] ?? ''} onChange={(event) => setPin({ ...pin, [delivery.id]: event.target.value.replace(/\D/g,'') })} className="mt-1 text-center tracking-[0.3em] font-extrabold"/></div>}
        {action && <Button disabled={busy === delivery.id || (delivery.status === 'ARRIVING' && pin[delivery.id]?.length !== 4)} onClick={() => void update(delivery, action.status)} className="w-full rounded-xl mt-4">{busy === delivery.id ? <Loader2 className="h-4 w-4 animate-spin"/> : <>{action.label}{delivery.status === 'ARRIVING' ? <Check className="h-4 w-4 ml-2"/> : <Truck className="h-4 w-4 ml-2"/>}</>}</Button>}
      </article>;
    })}{!deliveries.some((item) => bucket(item) === group) && <div className="border border-dashed rounded-2xl p-8 text-center text-sm text-gray-400">No deliveries here</div>}</section>)}</div>
  </div>;
}
